import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        int q = in.nextInt();
        int[] burst = new int[n];
        int[] rem = new int[n];
        ArrayDeque<Integer> queue = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            burst[i] = in.nextInt();
            rem[i] = burst[i];
            queue.add(i);
        }
        int time = 0;
        long totalWait = 0;
        while (!queue.isEmpty()) {
            int i = queue.poll();
            int run = Math.min(q, rem[i]);
            time += run;
            rem[i] -= run;
            if (rem[i] > 0) queue.add(i);
            else totalWait += time - burst[i];
        }
        System.out.println(String.format("%.2f", (double) totalWait / n));
    }
}
